//! Generates the C header for the FSKit extension.

use std::path::PathBuf;

fn main() {
    let crate_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let header = crate_dir.join("../../fskit/Extension/buildfs_ffi.h");
    println!("cargo:rerun-if-changed=src/lib.rs");
    let config = cbindgen::Config {
        language: cbindgen::Language::C,
        pragma_once: true,
        include_guard: Some("BUILDFS_FFI_H".into()),
        autogen_warning: Some(
            "/* Generated by crates/buildfs-ffi/build.rs (cbindgen). Do not edit. */".into(),
        ),
        documentation: true,
        style: cbindgen::Style::Both,
        sys_includes: vec!["stdbool.h".into(), "stddef.h".into(), "stdint.h".into()],
        no_includes: true,
        usize_is_size_t: true,
        ..Default::default()
    };
    match cbindgen::Builder::new()
        .with_crate(&crate_dir)
        .with_config(config)
        .generate()
    {
        Ok(b) => {
            let _ = b.write_to_file(header);
        }
        Err(e) => panic!("cbindgen failed: {e}"),
    }
}
